export declare const toolbarStyles = "\n/* ---- \u5DE5\u5177\u680F ---- */\n.wf-toolbar {\n  flex: none;\n  height: 52px;\n  min-height: 52px;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 12px;\n  background: var(--wf-layer);\n  border-bottom: 1px solid var(--wf-border);\n  flex-wrap: nowrap;\n  overflow-x: auto;\n  overflow-y: hidden;\n  scrollbar-width: thin;\n}\n\n.wf-toolbar>* {\n  flex: none;\n}\n\n.wf-toolbar__switch {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  color: var(--wf-ink-2);\n  font-size: 10px;\n  cursor: pointer;\n  white-space: nowrap;\n}\n\n.wf-toolbar__switch input {\n  width: auto;\n  flex: 0 0 auto;\n  min-width: 0;\n  margin: 0;\n  accent-color: var(--wf-brand);\n  cursor: pointer;\n}\n\n/* \u5DE5\u4F5C\u533A\u8DEF\u5F84\u9009\u62E9\uFF08\u6A21\u677F\u6001 + \u5DF2\u52FE\u9009\u300C\u5F00\u542F\u65B0\u4F1A\u8BDD\u300D\u65F6\u51FA\u73B0\uFF09\uFF1A\u6309\u94AE\u590D\u7528\u5B98\u65B9\u76EE\u5F55\u9009\u62E9\u5668\uFF0C\n   \u5DF2\u9009\u8DEF\u5F84\u663E\u793A\u5728\u6309\u94AE\u53F3\u65B9\u7528\u4E8E\u786E\u8BA4\uFF08\u8FC7\u957F\u7701\u7565\uFF0C\u5B8C\u6574\u8DEF\u5F84\u89C1 title\uFF09\u3002 */\n.wf-toolbar__workspace-pick {\n  font-size: 10px;\n}\n\n.wf-toolbar__workspace-path {\n  display: inline-block;\n  max-width: 260px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  vertical-align: middle;\n  color: var(--wf-ink-2);\n  font-size: 10px;\n}\n\n/* \u9876\u90E8\u4E00\u952E\u6298\u53E0/\u5C55\u5F00\u4E24\u4FA7\u6309\u94AE\uFF08\u6279\u6CE8\uFF1A\u6298\u53E0\u65F6\u56FE\u6807\u6CDB\u54C1\u724C\u8272\uFF0C\u63D0\u793A\u5F53\u524D\u53EF\u5C55\u5F00\uFF09 */\n.wf-toolbar__panels svg {\n  color: var(--wf-ink-2);\n}\n\n.wf-toolbar__panels.is-collapsed {\n  border-color: color-mix(in srgb, var(--wf-brand) 45%, var(--wf-border-strong));\n}\n\n.wf-toolbar__panels.is-collapsed svg {\n  color: var(--wf-brand);\n}\n\n/* ---- \u901A\u7528\u6309\u94AE\uFF08\u4E3B / \u5371\u9669 / \u5E7D\u7075 / \u7981\u7528\uFF09 ---- */\n.wf-btn {\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 8px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  padding: 6px 11px;\n  transition: border-color .15s ease, transform .15s ease, background .15s ease;\n  white-space: nowrap;\n}\n\n.wf-btn:hover {\n  border-color: var(--wf-brand);\n  transform: translateY(-1px);\n}\n\n/* \u4E3B\u6309\u94AE\uFF1A\u91C7\u7528 DSH \u5B98\u65B9\u4E3B\u6309\u94AE\u8BED\u4E49\uFF08--dsw-alias-button-primary-fill \u4E0E\n   --dsw-alias-label-primary-foreground\uFF09\uFF1A\u6DF1\u8272\u4E3B\u9898=\u6D45\u5E95\u6DF1\u5B57\u3001\u6D45\u8272\u4E3B\u9898=\u6DF1\u5E95\u767D\u5B57\uFF0C\n   \u65E0\u8BBA\u4E3B\u9898\u5982\u4F55\u90FD\u4FDD\u6301\u6587\u5B57\u53EF\u89C1\uFF08\u6B64\u524D fallback #fff \u5728\u6DF1\u8272\u4E3B\u9898\u6D45\u5E95\u4E0A\u767D\u5B57\u4E0D\u53EF\u89C1\uFF09 */\n.wf-btn.is-primary {\n  border-color: var(--dsw-alias-button-primary-fill, var(--wf-brand));\n  background: var(--dsw-alias-button-primary-fill, var(--wf-brand));\n  color: var(--dsw-alias-label-primary-foreground, var(--wf-bg));\n  font-weight: 650;\n}\n\n.wf-btn.is-primary:hover {\n  border-color: var(--dsw-alias-button-primary-hover, var(--wf-brand));\n}\n\n.wf-btn.is-danger {\n  border-color: color-mix(in srgb, var(--wf-err) 55%, var(--wf-border-strong));\n  color: var(--wf-err);\n}\n\n.wf-btn.is-danger:hover {\n  border-color: var(--wf-err);\n}\n\n.wf-btn.is-ghost {\n  background: transparent;\n}\n\n.wf-btn:disabled {\n  opacity: .5;\n  cursor: default;\n}\n\n/* ---- \u5DE5\u5177\u680F\u53F3\u4FA7\u72B6\u6001\u6587\u6848 ---- */\n.wf-status {\n  color: var(--wf-ink-2);\n  font-size: 12px;\n  margin-left: auto;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  max-width: 38%;\n}\n\n.wf-status.is-running {\n  color: var(--wf-ok);\n}\n";
